#[test]
fn running_cancel_and_generation_advance_suppress_publication() {
    for advance in [false, true] {
        let q = queue(2, 1);
        let (started_tx, started_rx) = mpsc::channel();
        enqueue(&q, 20, 1, move |token| {
            started_tx.send(()).unwrap();
            while !token.is_cancelled() { thread::yield_now(); }
            TaskOutput::success(20)
        }).unwrap();
        receive(&started_rx);
        if advance { assert_eq!(q.advance_generation(2), Ok(())); }
        else { assert_eq!(q.cancel(20), Ok(())); }
        q.shutdown();
        assert_eq!(q.poll(), None);
    }
    let q = queue(1, 1);
    assert_eq!(q.advance_generation(2), Ok(()));
    assert_eq!(q.advance_generation(2), Err(QueueError::Stale));
    assert_eq!(enqueue(&q, 21, 1, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Stale);
    let shared = Arc::new(42);
    enqueue_owned(&q, 22, 2, Arc::clone(&shared), |value, _| TaskOutput::success(**value)).unwrap();
    let deadline = std::time::Instant::now() + Duration::from_secs(3);
    let result = loop {
        if let Some(result) = q.poll() { break result; }
        assert!(std::time::Instant::now() < deadline, "shared-context completion timed out");
        thread::yield_now();
    };
    assert_eq!((result.id, result.value), (22, 42));
    q.shutdown();
}

