#[test]
fn status_priority_duplicate_full_stale_and_stopped() {
    let q = queue(2, 1);
    let (entered_tx, entered_rx) = mpsc::channel();
    let (release_tx, release_rx) = mpsc::channel();
    enqueue(&q, 1, 1, move |_| { entered_tx.send(()).unwrap(); receive(&release_rx); TaskOutput::success(1) }).unwrap();
    receive(&entered_rx);
    enqueue(&q, 2, 1, |_| TaskOutput::success(2)).unwrap();
    let duplicate = enqueue(&q, 2, 2, |_| TaskOutput::success(0)).unwrap_err();
    assert_eq!(duplicate.status, QueueError::Duplicate);
    assert_eq!(enqueue(&q, 3, 1, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Full);
    assert_eq!(enqueue(&q, 3, 2, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Stale);
    release_tx.send(()).unwrap();
    q.shutdown();
    assert_eq!(enqueue(&q, 0, 1, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Invalid);
    assert_eq!(enqueue(&q, 5, 1, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Stopped);
    assert_eq!(q.cancel(99), Err(QueueError::NotFound));
}

